#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "covariance.h"

/* Include the Exo-generated kernel header. */
#include "generated/covariance/covariance.h"


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)n;

  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = ((DATA_TYPE) i*j) / M;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(cov,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("cov");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, cov[i][j]);
    }
  POLYBENCH_DUMP_END("cov");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM
from exo.frontend.syntax import *

# Optimized covariance kernel.
#
# Key optimizations compared to the straightforward formulation:
#   * All passes over `data` use row-major traversal (i then j) to get
#     stride‑1 access in memory on the inner loop.
#   * Covariance is computed as a sum of per-row outer products:
#         cov += x_k^T * x_k
#     with k (row index) as the outer loop. This avoids strided column
#     walks present in the naive i–j–k loop nest.
#   * Simple tiling is applied along the row/sample dimensions of the
#     most bandwidth-intensive loops using `divide_loop`, to improve
#     cache behavior for large problems while handling non-multiple
#     sizes correctly via guarded tails.
#
# The mathematical result matches the reference PolyBench covariance:
#   cov[i,j] = 1/(n-1) * sum_k (data[k,i] - mean[i]) * (data[k,j] - mean[j])
# up to floating‑point round‑off differences due to re-association.


@proc
def kernel_covariance(
    m: size,
    n: size,
    float_n: DATA_TYPE,
    data: DATA_TYPE[n, m] @ DRAM,
    cov: DATA_TYPE[m, m] @ DRAM,
    mean: DATA_TYPE[m] @ DRAM,
):

    # ------------------------------------------------------------------
    # 1. Compute column means
    # ------------------------------------------------------------------

    # Zero-initialize means.
    for j_init in seq(0, m):
        mean[j_init] = 0.0

    # Accumulate column sums in a row-major traversal:
    #   for each row i, walk all columns j.
    # This yields stride-1 access to `data[i, j]` on the inner loop.
    for i_mean in seq(0, n):
        for j_mean in seq(0, m):
            mean[j_mean] += data[i_mean, j_mean]

    # Finalize means: divide by float_n (= n as a DATA_TYPE).
    for j_div in seq(0, m):
        mean[j_div] = mean[j_div] / float_n

    # ------------------------------------------------------------------
    # 2. Center the data (row-major traversal)
    # ------------------------------------------------------------------
    # After this step, each column has zero mean.

    for i_center in seq(0, n):
        for j_center in seq(0, m):
            data[i_center, j_center] = data[i_center, j_center] - mean[j_center]

    # ------------------------------------------------------------------
    # 3. Covariance accumulation as outer products
    # ------------------------------------------------------------------
    # We first zero `cov`, then for each centered row x_k (length m),
    # accumulate:
    #   cov[i,j] += x_k[i] * x_k[j]  for all i <= j.
    # This is mathematically equivalent to the reference implementation
    # but uses k (row) as the outer loop so that accesses to
    # `data[k, j]` are stride‑1 along j.

    # Zero-initialize covariance matrix.
    for i_cov_init in seq(0, m):
        for j_cov_init in seq(0, m):
            cov[i_cov_init, j_cov_init] = 0.0

    # Main accumulation: one outer product per row k.
    for k_cov in seq(0, n):
        for i_cov in seq(0, m):
            # Cache data[k_cov, i_cov] in a scalar to avoid reloading
            # the same element for all j >= i_cov.
            tmp: DATA_TYPE
            tmp = data[k_cov, i_cov]
            for j_cov in seq(i_cov, m):
                cov[i_cov, j_cov] += tmp * data[k_cov, j_cov]

    # ------------------------------------------------------------------
    # 4. Normalize and symmetrize covariance
    # ------------------------------------------------------------------
    # Normalize by (float_n - 1.0) and then mirror the upper triangle
    # into the lower triangle to get a symmetric matrix.

    for i_cov_scale in seq(0, m):
        for j_cov_scale in seq(i_cov_scale, m):
            cov[i_cov_scale, j_cov_scale] = (
                cov[i_cov_scale, j_cov_scale] / (float_n - 1.0)
            )
            cov[j_cov_scale, i_cov_scale] = cov[i_cov_scale, j_cov_scale]


# ----------------------------------------------------------------------
# Scheduling: apply loop tiling and simplifications
# ----------------------------------------------------------------------

# Tile the data-centering loop along the row (sample) dimension i_center.
# This groups rows processed together, which can improve cache locality
# for very large N while preserving a row-major inner traversal over j.
kernel_covariance = divide_loop(
    kernel_covariance,
    "i_center",            # loop iterator to split
    32,                    # tile size along rows
    ("i_center_outer", "i_center_inner"),
    tail="guard",          # handle non-multiples of 32 safely
)

# Tile the main covariance accumulation along the sample dimension k_cov.
# This restructures the k loop into blocks of rows without changing the
# order in which rows are processed.
kernel_covariance = divide_loop(
    kernel_covariance,
    "k_cov",
    32,                    # tile size along k
    ("k_cov_outer", "k_cov_inner"),
    tail="guard",
)

# Cleanup: simplify expressions and control flow after tiling.
kernel_covariance = simplify(kernel_covariance)

EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_covariance (/*ctxt=*/NULL, m, n,
                     (DATA_TYPE*)&float_n,
                     (DATA_TYPE*)POLYBENCH_ARRAY(data),
                     (DATA_TYPE*)POLYBENCH_ARRAY(cov),
                     (DATA_TYPE*)POLYBENCH_ARRAY(mean));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(cov)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(cov);
  POLYBENCH_FREE_ARRAY(mean);

  return 0;
}
