from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# ---------------------------------------------------------------------------
# Baseline kernel: direct, readable transcription of the PolyBench covariance
# ---------------------------------------------------------------------------

@proc
def kernel_covariance_base(
    m: size,
    n: size,
    float_n: DATA_TYPE,
    data: DATA_TYPE[n, m] @ DRAM,
    cov: DATA_TYPE[m, m] @ DRAM,
    mean: DATA_TYPE[m] @ DRAM,
):
    # Basic sanity: at least two rows are needed for an unbiased estimator.
    assert n > 1
    assert m > 0

    # 1) Initialize column means.
    for j in seq(0, m):
        mean[j] = 0.0

    # 2) Accumulate column sums.
    #    This matches the original algorithm structurally, but we will
    #    later reorder these loops for better spatial locality.
    for j in seq(0, m):
        for i in seq(0, n):
            mean[j] += data[i, j]

    # 3) Normalize to get the mean of each column.
    for j in seq(0, m):
        mean[j] = mean[j] / float_n

    # 4) Center the data: subtract mean of each column from every row.
    for i in seq(0, n):
        for j in seq(0, m):
            data[i, j] = data[i, j] - mean[j]

    # 5) Compute the covariance matrix.
    #    We compute the upper triangle and explicitly mirror it to keep
    #    the cost close to the PolyBench reference while exploiting symmetry.
    for i in seq(0, m):
        for j in seq(i, m):
            cov[i, j] = 0.0

            for k in seq(0, n):
                cov[i, j] += data[k, i] * data[k, j]

            cov[i, j] = cov[i, j] / (float_n - 1.0)
            cov[j, i] = cov[i, j]


