#
#    Loop shape:
#        for i in 0..m-1:
#          for j in i..m-1:
#            cov[i, j] = 0.0
#            for k in 0..n-1:
#              cov[i, j] += data[k, i] * data[k, j]
#            cov[i, j] /= (float_n - 1.0)
#            cov[j, i] = cov[i, j]
#
#    For a fixed `i`, this loop writes exactly once to all pairs
#    (i, j) and (j, i) with j >= i. No other `i' != i` iteration ever
#    touches those same locations, so the i-iterations are independent and
#    can safely be executed in parallel.
kernel_covariance = parallelize_loop(
    kernel_covariance,
    kernel_covariance.find_loop("i #2"),
)

# 4) Run a simplification pass to clean up any algebraically redundant
#    expressions or dead loops introduced by transformations.
kernel_covariance = simplify(kernel_covariance)
