from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base covariance kernel: written for good memory locality
# (row-major traversal where possible), then scheduled.
@proc
def covariance_base(
    m: size,
    n: size,
    float_n: DATA_TYPE,
    data: DATA_TYPE[n, m] @ DRAM,
    cov: DATA_TYPE[m, m] @ DRAM,
    mean: DATA_TYPE[m] @ DRAM,
):
    # PolyBench always uses n > 1 (otherwise float_n - 1 would be zero).
    assert n > 1

    # 1. Initialize column means to zero.
    for j in seq(0, m):
        mean[j] = 0.0

    # 2. Accumulate column sums.
    #    We iterate over rows first and columns inside to follow the
    #    row-major layout of `data` (data[i, j] is contiguous in j).
    for i in seq(0, n):
        for j in seq(0, m):
            mean[j] += data[i, j]

    # 3. Normalize means: mean[j] = (1 / n) * sum_i data[i, j].
    for j in seq(0, m):
        mean[j] = mean[j] / float_n

    # 4. Center the data in-place by subtracting the column means.
    #    Again, rows are outer and columns inner for better locality.
    for i in seq(0, n):
